//! Frame a confined shell's output and raw termination without exit-code guessing.
use std::io::{Read,Write};
use std::os::unix::process::ExitStatusExt;
fn main(){let command=std::env::args().nth(1).expect("command argument");let mut c=std::process::Command::new("bash").args(["-c",&command]).stdin(std::process::Stdio::null()).stdout(std::process::Stdio::piped()).stderr(std::process::Stdio::piped()).spawn().expect("spawn shell");let emit=std::sync::Arc::new(std::sync::Mutex::new(std::io::stdout()));let mut threads=vec![];for (channel,mut reader) in [("stdout",Box::new(c.stdout.take().unwrap()) as Box<dyn Read+Send>),("stderr",Box::new(c.stderr.take().unwrap()) as Box<dyn Read+Send>)]{let emit=emit.clone();threads.push(std::thread::spawn(move||{let mut buf=[0u8;4096];loop{match reader.read(&mut buf){Ok(0)=>break,Ok(n)=>{let mut w=emit.lock().unwrap();serde_json::to_writer(&mut *w,&serde_json::json!({"channel":channel,"bytes":&buf[..n]})).unwrap();w.write_all(b"\n").unwrap();w.flush().unwrap();},Err(e) if e.kind()==std::io::ErrorKind::Interrupted=>continue,Err(e)=>{let mut w=emit.lock().unwrap();serde_json::to_writer(&mut *w,&serde_json::json!({"error":format!("{channel} read failed: {e}")})).unwrap();w.write_all(b"\n").unwrap();break}}}}));}let status=c.wait().expect("wait shell");for t in threads{t.join().expect("output thread");}let mut w=emit.lock().unwrap();serde_json::to_writer(&mut *w,&serde_json::json!({"exit_code":status.code(),"signal":status.signal(),"settled":true})).unwrap();w.write_all(b"\n").unwrap();}
